1	package com.example.starter.idempotency;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.Optional;
8	
9	import com.example.starter.common.ApiException;
10	import com.fasterxml.jackson.core.JsonProcessingException;
11	import com.fasterxml.jackson.databind.ObjectMapper;
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.stereotype.Service;
15	
16	/**
17	 * 幂等控制：以 (requestId, endpoint) 为键，指纹覆盖 requestId 与全部业务字段。
18	 * 同键同参返回首次结果；同键异参返回 409 且不执行业务、不改变额度。
19	 * 业务事务开始时先插入占位记录，事务提交时写入首次响应；
20	 * 并发同键请求因主键冲突回滚后重读已提交记录并重放。
21	 */
22	@Service
23	public class IdempotencyService {
24	
25	    private final JdbcTemplate jdbc;
26	    private final ObjectMapper objectMapper;
27	
28	    public IdempotencyService(JdbcTemplate jdbc, ObjectMapper objectMapper) {
29	        this.jdbc = jdbc;
30	        this.objectMapper = objectMapper;
31	    }
32	
33	    /**
34	     * 计算请求指纹：endpoint + requestId + 全部业务字段的规范化 JSON 的 SHA-256。
35	     */
36	    public String fingerprint(String endpoint, Object requestDto) {
37	        String canonical;
38	        try {
39	            canonical = objectMapper.writeValueAsString(requestDto);
40	        } catch (JsonProcessingException e) {
41	            throw new IllegalStateException("请求序列化失败", e);
42	        }
43	        return sha256(endpoint + '|' + canonical);
44	    }
45	
46	    /**
47	     * 在业务事务内插入幂等占位记录；同键已存在时抛出 {@link DuplicateKeyException} 使事务回滚。
48	     */
49	    public void begin(String endpoint, String requestId, String fingerprint) {
50	        jdbc.update(
51	                "INSERT INTO idempotency_record (request_id, endpoint, fingerprint, response_status, response_body)"
52	                        + " VALUES (?, ?, ?, 0, '')",
53	                requestId, endpoint, fingerprint);
54	    }
55	
56	    /**
57	     * 在业务事务内写入首次响应，随业务同事务提交。
58	     */
59	    public void complete(String endpoint, String requestId, int status, Object responseBody) {
60	        String body;
61	        try {
62	            body = objectMapper.writeValueAsString(responseBody);
63	        } catch (JsonProcessingException e) {
64	            throw new IllegalStateException("响应序列化失败", e);
65	        }
66	        jdbc.update(
67	                "UPDATE idempotency_record SET response_status = ?, response_body = ?"
68	                        + " WHERE request_id = ? AND endpoint = ?",
69	                status, body, requestId, endpoint);
70	    }
71	
72	    /**
73	     * 读取已提交的幂等记录。
74	     */
75	    public Optional<StoredResponse> find(String endpoint, String requestId) {
76	        return jdbc.query(
77	                        "SELECT fingerprint, response_status, response_body FROM idempotency_record"
78	                                + " WHERE request_id = ? AND endpoint = ?",
79	                        (rs, rowNum) -> new StoredResponse(
80	                                rs.getString("fingerprint"),
81	                                rs.getInt("response_status"),
82	                                rs.getString("response_body")),
83	                        requestId, endpoint)
84	                .stream()
85	                .findFirst();
86	    }
