263	        CountDownLatch gate = new CountDownLatch(1);
264	        AtomicInteger success = new AtomicInteger();
265	        AtomicInteger rejected = new AtomicInteger();
266	        try {
267	            List<Future<?>> futures = new java.util.ArrayList<>();
268	            for (int i = 0; i < threads; i++) {
269	                String requestId = "REQ-C-" + i;
270	                futures.add(pool.submit(() -> {
271	                    try {
272	                        gate.await(10, TimeUnit.SECONDS);
273	                        issue("S1", requestId,
274	                                List.of(new LineRequest("货物", amount)));
275	                        success.incrementAndGet();
276	                    } catch (ApiException e) {
277	                        assertThat(e.getCode()).isEqualTo("INSUFFICIENT_CREDIT");
278	                        rejected.incrementAndGet();
279	                    } catch (InterruptedException e) {
280	                        Thread.currentThread().interrupt();
281	                    }
282	                }));
283	            }
284	            gate.countDown();
285	            for (Future<?> future : futures) {
286	                future.get(30, TimeUnit.SECONDS);
287	            }
288	        } finally {
289	            pool.shutdownNow();
290	        }
291	        // 1000 / 150 = 6 张成功（900），第 7 张起拒绝
292	        assertThat(success.get()).isEqualTo(6);
293	        assertThat(rejected.get()).isEqualTo(4);
